create or replace function public.is_org_member(target_org uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=auth.uid()); $$;
create or replace function public.is_org_admin(target_org uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=auth.uid() and m.role in ('agency_admin','agency_staff')); $$;
create or replace function public.is_property_member(target_property uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.property_users p where p.property_id=target_property and p.user_id=auth.uid()) or exists(select 1 from public.properties p join public.organization_members m on m.organization_id=p.organization_id where p.id=target_property and m.user_id=auth.uid()); $$;
create or replace function public.is_property_admin(target_property uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.properties p join public.organization_members m on m.organization_id=p.organization_id where p.id=target_property and m.user_id=auth.uid() and m.role in ('agency_admin','agency_staff')) or exists(select 1 from public.property_users pu where pu.property_id=target_property and pu.user_id=auth.uid() and pu.role in ('property_owner','property_manager')); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
